import Foundation
import MLX

struct ChatRequestIssue: Error, LocalizedError {
    let option: String
    let message: String
    init(_ option: String, _ message: String) { self.option = option; self.message = message }
    var errorDescription: String? { "\(option): \(message)" }
}

@main struct Harness {
    static func main() throws {
        let args = CommandLine.arguments
        guard args.count == 4 || args.count == 5 else { throw ChatRequestIssue("arguments", "model-root suite output [calibration-file]") }
        try Device.withDefaultDevice(Device(.gpu)) {
            Memory.cacheLimit = 256 * 1024 * 1024
            try KolibriLogprobBenchmark.run(modelRoot: URL(fileURLWithPath: args[1]),
                suite: URL(fileURLWithPath: args[2]), output: URL(fileURLWithPath: args[3]),
                calibrationOutput: args.count == 5 ? URL(fileURLWithPath: args[4]) : nil,
                progressHandler: { FileHandle.standardError.write(Data(($0 + "\n").utf8)) })
        }
    }
}
